"""Source of truth for catalog/sources.json. Edit here, then run:  python3 catalog/build_catalog.py"""
import json, pathlib

V_GIT = "2026-11-16 git probe (repo exists, licence file read)"
V_WEB = "2026-11-16 web search (not machine-checked)"

def kaykit(id_, repo, folder, cats, what, n):
    return dict(id=id_, name=repo.replace("-", " "), url=f"https://github.com/KayKit-Game-Assets/{repo}",
        kind="asset-pack", style="low-poly stylised", categories=cats, what=what, count=n,
        license="CC0-1.0", credit="Kay Lousberg, kaylousberg.com (optional)", formats=["gltf", "fbx", "obj"],
        fetch=dict(method="git", repo=f"KayKit-Game-Assets/{repo}", paths=[f"addons/{folder}"]), verified=V_GIT)

