ids = [s["id"] for s in S]
assert len(ids) == len(set(ids)), "duplicate ids"
out = pathlib.Path(__file__).with_name("sources.json")
out.write_text(json.dumps(dict(version=1, generated="2026-11-16", sources=S), indent=1, ensure_ascii=False) + "\n")
print(f"wrote {out} with {len(S)} sources")
